INSERT INTO repo_kfrs (kfr_id, name, domain, discipline, function_type, function_granularity, definition, scope, purpose, inputs, outputs, realization_or_mechanism, semantic_description, keywords_synonyms, status) VALUES ('KFR_000001', 'Apply Pigeonhole Principle to Pigeonhole principle', 'Engineering & Technology', 'Computer Science; Discrete Mathematics', 'Analysis / Application', 'Atomic', 'Operational capability to apply Pigeonhole Principle to Pigeonhole principle under the governing principle''s stated assumptions and validity conditions.', 'Applies to finite counting and allocation arguments in which the number of objects exceeds the number of available categories or containers; it does not by itself identify which container contains the repeated objects.', 'Use Pigeonhole Principle to obtain a technically justified analysis, calculation, classification, or decision concerning Pigeonhole principle.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Pigeonhole principle.', 'A principle-grounded analysis, calculation, classification, or decision concerning Pigeonhole principle.', 'Verify the applicability conditions of Pigeonhole Principle, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Pigeonhole Principle for Pigeonhole principle. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Pigeonhole Principle; Pigeonhole principle', 'Active'), ('KFR_000002', 'Apply Principle of Mathematical Induction to Induction', 'Engineering & Technology', 'Computer Science; Discrete Mathematics', 'Analysis / Application', 'Atomic', 'Operational capability to apply Principle of Mathematical Induction to Induction under the governing principle''s stated assumptions and validity conditions.', 'Applies to statements indexed over an inductive domain such as the natural numbers; the induction step must explicitly establish the implication from the assumed case to the successor case.', 'Use Principle of Mathematical Induction to obtain a technically justified analysis, calculation, classification, or decision concerning Induction.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Induction.', 'A principle-grounded analysis, calculation, classification, or decision concerning Induction.', 'Verify the applicability conditions of Principle of Mathematical Induction, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Principle of Mathematical Induction for Induction. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Principle of Mathematical Induction; Induction', 'Active'), ('KFR_000003', 'Apply Equivalence-Class Principle to Equivalence relations', 'Engineering & Technology', 'Computer Science; Discrete Mathematics', 'Analysis / Application', 'Atomic', 'Operational capability to apply Equivalence-Class Principle to Equivalence relations under the governing principle''s stated assumptions and validity conditions.', 'Applies when the relation is reflexive, symmetric, and transitive. It should not be generalized to arbitrary relations.', 'Use Equivalence-Class Principle to obtain a technically justified analysis, calculation, classification, or decision concerning Equivalence relations.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Equivalence relations.', 'A principle-grounded analysis, calculation, classification, or decision concerning Equivalence relations.', 'Verify the applicability conditions of Equivalence-Class Principle, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Equivalence-Class Principle for Equivalence relations. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Equivalence-Class Principle; Equivalence relations', 'Active'), ('KFR_000004', 'Formulate and check mass conservation balances using Conservation of Mass', 'Engineering & Technology', 'Chemical Engineering; Civil Engineering; Mechanical Engineering', 'Balance / Analysis', 'Atomic', 'Operational capability to apply Conservation of Mass to mass conservation, Continuity under the governing principle''s stated assumptions and validity conditions.', 'Applies to defined system or control-volume boundaries and requires consistent accounting of all relevant mass streams; chemical reaction changes species composition but does not destroy total mass in ordinary engineering balances.', 'Use Conservation of Mass to obtain a technically justified analysis, calculation, classification, or decision concerning mass conservation, Continuity.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to mass conservation, Continuity.', 'A principle-grounded analysis, calculation, classification, or decision concerning mass conservation, Continuity.', 'Verify the applicability conditions of Conservation of Mass, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Conservation of Mass for mass conservation, Continuity. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Conservation of Mass; mass conservation, Continuity; mass conservation; Continuity', 'Active'), ('KFR_000005', 'Formulate and check Energy equation balances using Conservation of Energy', 'Engineering & Technology', 'Mechanical Engineering; Chemical Engineering; Civil Engineering', 'Balance / Analysis', 'Atomic', 'Operational capability to apply Conservation of Energy to Energy equation, energy balances, vapour-compression cycle, refrigeration effect, pressure-enthalpy analysis, sensible and latent loads, heat gains, Otto cycle, Diesel cycle, dual cycle, heat release, brake power, indicated power under the governing principle''s stated assumptions and validity conditions.', 'Applies to properly defined system boundaries and consistent energy accounting. It does not imply that energy quality or ability to perform useful work is conserved.', 'Use Conservation of Energy to obtain a technically justified analysis, calculation, classification, or decision concerning Energy equation, energy balances, vapour-compression cycle, refrigeration effect, pressure-enthalpy analysis, sensible and latent loads, heat gains, Otto cycle, Diesel cycle, dual cycle, heat release, brake power, indicated power.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Energy equation, energy balances, vapour-compression cycle, refrigeration effect, pressure-enthalpy analysis, sensible and latent loads, heat gains, Otto cycle, Diesel cycle, dual cycle, heat release, brake power, indicated power.', 'A principle-grounded analysis, calculation, classification, or decision concerning Energy equation, energy balances, vapour-compression cycle, refrigeration effect, pressure-enthalpy analysis, sensible and latent loads, heat gains, Otto cycle, Diesel cycle, dual cycle, heat release, brake power, indicated power.', 'Verify the applicability conditions of Conservation of Energy, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Conservation of Energy for Energy equation, energy balances, vapour-compression cycle, refrigeration effect, pressure-enthalpy analysis, sensible and latent loads, heat gains, Otto cycle, Diesel cycle, dual cycle, heat release, brake power, indicated power. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Conservation of Energy; Energy equation, energy balances, vapour-compression cycle, refrigeration effect; Energy equation; energy balances; vapour-compression cycle; refrigeration effect; pressure-enthalpy analysis; sensible and latent loads', 'Active'), ('KFR_000006', 'Apply Second Law of Thermodynamics to Second-law analysis', 'Engineering & Technology', 'Mechanical Engineering; Chemical Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Second Law of Thermodynamics to Second-law analysis, Entropy generation, Coefficient of Performance (COP), Coefficient of Performance / Energy Efficiency Ratio (COP/EER) under the governing principle''s stated assumptions and validity conditions.', 'Applies to thermodynamic processes and cycles subject to the stated system boundaries and equilibrium assumptions; it constrains achievable conversion efficiency and distinguishes reversible from irreversible processes.', 'Use Second Law of Thermodynamics to obtain a technically justified analysis, calculation, classification, or decision concerning Second-law analysis, Entropy generation, Coefficient of Performance (COP), Coefficient of Performance / Energy Efficiency Ratio (COP/EER).', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Second-law analysis, Entropy generation, Coefficient of Performance (COP), Coefficient of Performance / Energy Efficiency Ratio (COP/EER).', 'A principle-grounded analysis, calculation, classification, or decision concerning Second-law analysis, Entropy generation, Coefficient of Performance (COP), Coefficient of Performance / Energy Efficiency Ratio (COP/EER).', 'Verify the applicability conditions of Second Law of Thermodynamics, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Second Law of Thermodynamics for Second-law analysis, Entropy generation, Coefficient of Performance (COP), Coefficient of Performance / Energy Efficiency Ratio (COP/EER). The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Second Law of Thermodynamics; Second-law analysis, Entropy generation, COP, COP/EER; Second-law analysis; Entropy generation; Coefficient of Performance (COP); Coefficient of Performance / Energy Efficiency Ratio (COP/EER)', 'Active'), ('KFR_000007', 'Apply Newton''s Second Law of Motion to force', 'Engineering & Technology', 'Mechanical Engineering; Civil Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Newton''s Second Law of Motion to force, Velocity and acceleration fields, momentum balance under the governing principle''s stated assumptions and validity conditions.', 'Applies in inertial reference frames and with forces defined consistently. The simple F = ma form assumes constant mass; variable-mass systems require momentum accounting.', 'Use Newton''s Second Law of Motion to obtain a technically justified analysis, calculation, classification, or decision concerning force, Velocity and acceleration fields, momentum balance.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to force, Velocity and acceleration fields, momentum balance.', 'A principle-grounded analysis, calculation, classification, or decision concerning force, Velocity and acceleration fields, momentum balance.', 'Verify the applicability conditions of Newton''s Second Law of Motion, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Newton''s Second Law of Motion for force, Velocity and acceleration fields, momentum balance. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Newton''s Second Law of Motion; force, Velocity and acceleration fields, momentum balance; force; Velocity and acceleration fields; momentum balance', 'Active'), ('KFR_000008', 'Apply Newton''s Third Law to force', 'Engineering & Technology', 'Mechanical Engineering; Civil Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Newton''s Third Law to force under the governing principle''s stated assumptions and validity conditions.', 'Applies to paired interaction forces between bodies; the forces act on different bodies and therefore should not be cancelled within the free-body diagram of a single body.', 'Use Newton''s Third Law to obtain a technically justified analysis, calculation, classification, or decision concerning force.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to force.', 'A principle-grounded analysis, calculation, classification, or decision concerning force.', 'Verify the applicability conditions of Newton''s Third Law, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Newton''s Third Law for force. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Newton''s Third Law; force', 'Active'), ('KFR_000009', 'Apply Hooke''s Law to Hooke''s Law', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering', 'Prediction / Calculation', 'Atomic', 'Operational capability to apply Hooke''s Law to Hooke''s Law, mechanical properties, stiffness under the governing principle''s stated assumptions and validity conditions.', 'Applies only within the specified linear-elastic regime and under the assumptions of the adopted material model; it does not describe plastic or strongly nonlinear response.', 'Use Hooke''s Law to obtain a technically justified analysis, calculation, classification, or decision concerning Hooke''s Law, mechanical properties, stiffness.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Hooke''s Law, mechanical properties, stiffness.', 'A principle-grounded analysis, calculation, classification, or decision concerning Hooke''s Law, mechanical properties, stiffness.', 'Verify the applicability conditions of Hooke''s Law, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Hooke''s Law for Hooke''s Law, mechanical properties, stiffness. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Hooke''s Law; Hooke''s Law, mechanical properties, stiffness; mechanical properties; stiffness', 'Active'), ('KFR_000010', 'Apply Principle of Superposition to Laplace transforms', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering; Electrical Engineering', 'Analysis / Application', 'Atomic', 'Operational capability to apply Principle of Superposition to Laplace transforms, system properties under the governing principle''s stated assumptions and validity conditions.', 'Requires linearity of the governing system over the range considered. It does not generally apply to nonlinear material behaviour, nonlinear circuits, or nonlinear dynamics.', 'Use Principle of Superposition to obtain a technically justified analysis, calculation, classification, or decision concerning Laplace transforms, system properties.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Laplace transforms, system properties.', 'A principle-grounded analysis, calculation, classification, or decision concerning Laplace transforms, system properties.', 'Verify the applicability conditions of Principle of Superposition, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Principle of Superposition for Laplace transforms, system properties. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Principle of Superposition; Laplace transforms, system properties; Laplace transforms; system properties', 'Active'), ('KFR_000011', 'Formulate and check Continuity balances using Continuity Principle', 'Engineering & Technology', 'Civil Engineering; Chemical Engineering; Mechanical Engineering', 'Balance / Analysis', 'Atomic', 'Operational capability to apply Continuity Principle to Continuity, Control volumes, mass conservation under the governing principle''s stated assumptions and validity conditions.', 'Applies to defined control volumes or streamtubes with consistent density, velocity, and area descriptions; simplified forms require the relevant steady-state and incompressibility assumptions.', 'Use Continuity Principle to obtain a technically justified analysis, calculation, classification, or decision concerning Continuity, Control volumes, mass conservation.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Continuity, Control volumes, mass conservation.', 'A principle-grounded analysis, calculation, classification, or decision concerning Continuity, Control volumes, mass conservation.', 'Verify the applicability conditions of Continuity Principle, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Continuity Principle for Continuity, Control volumes, mass conservation. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Continuity Principle; Continuity, Control volumes, mass conservation; Continuity; Control volumes; mass conservation', 'Active'), ('KFR_000012', 'Apply Bernoulli Principle to Bernoulli equation', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering', 'Analysis / Application', 'Atomic', 'Operational capability to apply Bernoulli Principle to Bernoulli equation under the governing principle''s stated assumptions and validity conditions.', 'The elementary form applies to steady, incompressible, inviscid flow along a streamline with no shaft work or heat-transfer contribution between the selected points; extended energy equations are required otherwise.', 'Use Bernoulli Principle to obtain a technically justified analysis, calculation, classification, or decision concerning Bernoulli equation.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Bernoulli equation.', 'A principle-grounded analysis, calculation, classification, or decision concerning Bernoulli equation.', 'Verify the applicability conditions of Bernoulli Principle, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Bernoulli Principle for Bernoulli equation. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Bernoulli Principle; Bernoulli equation', 'Active'), ('KFR_000013', 'Apply Darcy''s Law to Darcy''s law', 'Engineering & Technology', 'Civil Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Darcy''s Law to Darcy''s law, Soil permeability, well hydraulics, infiltration under the governing principle''s stated assumptions and validity conditions.', 'Applies to laminar flow through porous media represented by an appropriate hydraulic conductivity and gradient; it is not a universal law for non-Darcy or highly inertial porous-media flow.', 'Use Darcy''s Law to obtain a technically justified analysis, calculation, classification, or decision concerning Darcy''s law, Soil permeability, well hydraulics, infiltration.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Darcy''s law, Soil permeability, well hydraulics, infiltration.', 'A principle-grounded analysis, calculation, classification, or decision concerning Darcy''s law, Soil permeability, well hydraulics, infiltration.', 'Verify the applicability conditions of Darcy''s Law, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Darcy''s Law for Darcy''s law, Soil permeability, well hydraulics, infiltration. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Darcy''s Law; Darcy''s law, Soil permeability, well hydraulics, infiltration; Soil permeability; well hydraulics; infiltration', 'Active'), ('KFR_000014', 'Evaluate Mohr-Coulomb failure criterion using Mohr-Coulomb Failure Criterion', 'Engineering & Technology', 'Civil Engineering', 'Analysis / Decision', 'Atomic', 'Operational capability to apply Mohr-Coulomb Failure Criterion to Mohr-Coulomb failure criterion, shear strength under the governing principle''s stated assumptions and validity conditions.', 'Applies as an idealized frictional failure criterion for soils and rocks within the assumptions of the selected effective-stress and strength model; it does not capture all nonlinear or strain-dependent failure behaviour.', 'Use Mohr-Coulomb Failure Criterion to obtain a technically justified analysis, calculation, classification, or decision concerning Mohr-Coulomb failure criterion, shear strength.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Mohr-Coulomb failure criterion, shear strength.', 'A principle-grounded analysis, calculation, classification, or decision concerning Mohr-Coulomb failure criterion, shear strength.', 'Verify the applicability conditions of Mohr-Coulomb Failure Criterion, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Mohr-Coulomb Failure Criterion for Mohr-Coulomb failure criterion, shear strength. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Mohr-Coulomb Failure Criterion; Mohr-Coulomb failure criterion, shear strength; shear strength', 'Active'), ('KFR_000015', 'Apply Fourier''s Law of Heat Conduction to Fourier law', 'Engineering & Technology', 'Mechanical Engineering; Chemical Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Fourier''s Law of Heat Conduction to Fourier law under the governing principle''s stated assumptions and validity conditions.', 'Applies to conductive heat transfer within the assumptions of the constitutive model; thermal conductivity may depend on temperature, direction, material state, and microstructure.', 'Use Fourier''s Law of Heat Conduction to obtain a technically justified analysis, calculation, classification, or decision concerning Fourier law.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Fourier law.', 'A principle-grounded analysis, calculation, classification, or decision concerning Fourier law.', 'Verify the applicability conditions of Fourier''s Law of Heat Conduction, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Fourier''s Law of Heat Conduction for Fourier law. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Fourier''s Law of Heat Conduction; Fourier law', 'Active'), ('KFR_000016', 'Apply Fick''s First Law to Fick law', 'Engineering & Technology', 'Chemical Engineering; Mechanical Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Fick''s First Law to Fick law, diffusion, molecular diffusion, mass-transfer coefficients under the governing principle''s stated assumptions and validity conditions.', 'Applies primarily to steady or quasi-steady diffusion representations with an appropriate concentration coordinate and constant or specified diffusivity; transient accumulation requires the second law.', 'Use Fick''s First Law to obtain a technically justified analysis, calculation, classification, or decision concerning Fick law, diffusion, molecular diffusion, mass-transfer coefficients.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Fick law, diffusion, molecular diffusion, mass-transfer coefficients.', 'A principle-grounded analysis, calculation, classification, or decision concerning Fick law, diffusion, molecular diffusion, mass-transfer coefficients.', 'Verify the applicability conditions of Fick''s First Law, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Fick''s First Law for Fick law, diffusion, molecular diffusion, mass-transfer coefficients. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Fick''s First Law; Fick law, diffusion, molecular diffusion, mass-transfer coefficients; Fick law; diffusion; molecular diffusion; mass-transfer coefficients', 'Active'), ('KFR_000017', 'Apply Arrhenius Temperature Dependence to Arrhenius equation', 'Engineering & Technology', 'Chemical Engineering', 'Prediction / Calculation', 'Atomic', 'Operational capability to apply Arrhenius Temperature Dependence to Arrhenius equation under the governing principle''s stated assumptions and validity conditions.', 'Applies to reaction systems for which the Arrhenius representation is an adequate kinetic model over the stated temperature range; it is not a universal mechanistic explanation of all temperature effects.', 'Use Arrhenius Temperature Dependence to obtain a technically justified analysis, calculation, classification, or decision concerning Arrhenius equation.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to Arrhenius equation.', 'A principle-grounded analysis, calculation, classification, or decision concerning Arrhenius equation.', 'Verify the applicability conditions of Arrhenius Temperature Dependence, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Arrhenius Temperature Dependence for Arrhenius equation. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Arrhenius Temperature Dependence; Arrhenius equation', 'Active'), ('KFR_000018', 'Apply Le Chatelier''s Principle to equilibrium relations', 'Engineering & Technology', 'Chemical Engineering', 'Analysis / Application', 'Atomic', 'Operational capability to apply Le Chatelier''s Principle to equilibrium relations, vapour-liquid equilibrium under the governing principle''s stated assumptions and validity conditions.', 'Applies to systems at or near chemical equilibrium under the specified perturbation; it predicts the direction of response rather than providing the complete quantitative equilibrium composition.', 'Use Le Chatelier''s Principle to obtain a technically justified analysis, calculation, classification, or decision concerning equilibrium relations, vapour-liquid equilibrium.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to equilibrium relations, vapour-liquid equilibrium.', 'A principle-grounded analysis, calculation, classification, or decision concerning equilibrium relations, vapour-liquid equilibrium.', 'Verify the applicability conditions of Le Chatelier''s Principle, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Le Chatelier''s Principle for equilibrium relations, vapour-liquid equilibrium. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Le Chatelier''s Principle; equilibrium relations, vapour-liquid equilibrium; equilibrium relations; vapour-liquid equilibrium', 'Active'), ('KFR_000019', 'Apply Law of Mass Action to equilibrium relations', 'Engineering & Technology', 'Chemical Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Law of Mass Action to equilibrium relations, rate laws, elementary reactions under the governing principle''s stated assumptions and validity conditions.', 'Applies to reactions represented under the adopted thermodynamic and concentration/activity convention; equilibrium constants depend on temperature and the chosen standard-state formulation.', 'Use Law of Mass Action to obtain a technically justified analysis, calculation, classification, or decision concerning equilibrium relations, rate laws, elementary reactions.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to equilibrium relations, rate laws, elementary reactions.', 'A principle-grounded analysis, calculation, classification, or decision concerning equilibrium relations, rate laws, elementary reactions.', 'Verify the applicability conditions of Law of Mass Action, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Law of Mass Action for equilibrium relations, rate laws, elementary reactions. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Law of Mass Action; equilibrium relations, rate laws, elementary reactions; equilibrium relations; rate laws; elementary reactions', 'Active'), ('KFR_000020', 'Apply Ohm''s Law to equivalent circuit', 'Engineering & Technology', 'Electrical Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Ohm''s Law to equivalent circuit under the governing principle''s stated assumptions and validity conditions.', 'Applies to elements exhibiting approximately linear voltage-current behaviour over the operating range; many semiconductor and nonlinear devices do not obey a constant-resistance form.', 'Use Ohm''s Law to obtain a technically justified analysis, calculation, classification, or decision concerning equivalent circuit.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to equivalent circuit.', 'A principle-grounded analysis, calculation, classification, or decision concerning equivalent circuit.', 'Verify the applicability conditions of Ohm''s Law, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Ohm''s Law for equivalent circuit. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Ohm''s Law; equivalent circuit', 'Active'), ('KFR_000021', 'Formulate and check current-source inverters balances using Kirchhoff''s Current Law', 'Engineering & Technology', 'Electrical Engineering', 'Balance / Analysis', 'Atomic', 'Operational capability to apply Kirchhoff''s Current Law to current-source inverters under the governing principle''s stated assumptions and validity conditions.', 'Applies at circuit nodes under the adopted lumped-element approximation; displacement-current effects and distributed electromagnetic behaviour may require a field-based treatment.', 'Use Kirchhoff''s Current Law to obtain a technically justified analysis, calculation, classification, or decision concerning current-source inverters.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to current-source inverters.', 'A principle-grounded analysis, calculation, classification, or decision concerning current-source inverters.', 'Verify the applicability conditions of Kirchhoff''s Current Law, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Kirchhoff''s Current Law for current-source inverters. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Kirchhoff''s Current Law; current-source inverters', 'Active'), ('KFR_000022', 'Apply Faraday''s Law of Electromagnetic Induction to transformers', 'Engineering & Technology', 'Electrical Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Faraday''s Law of Electromagnetic Induction to transformers, induced EMF, ideal transformer under the governing principle''s stated assumptions and validity conditions.', 'Applies to electromagnetic induction with the sign convention represented by Lenz''s law; circuit-level and field-level formulations must use compatible definitions of flux and induced emf.', 'Use Faraday''s Law of Electromagnetic Induction to obtain a technically justified analysis, calculation, classification, or decision concerning transformers, induced EMF, ideal transformer.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to transformers, induced EMF, ideal transformer.', 'A principle-grounded analysis, calculation, classification, or decision concerning transformers, induced EMF, ideal transformer.', 'Verify the applicability conditions of Faraday''s Law of Electromagnetic Induction, map the concept-specific variables and relationships to the principle, and derive only the conclusions permitted by that principle.', 'Operationalizes Faraday''s Law of Electromagnetic Induction for transformers, induced EMF, ideal transformer. The function connects concept-specific evidence to a principle-grounded result within the stated scope and should not be generalized beyond the principle''s assumptions.', 'Faraday''s Law of Electromagnetic Induction; transformers, induced EMF, ideal transformer; transformers; induced EMF; ideal transformer', 'Active'), ('KFR_000023', 'Apply Lenz''s Law to transformers', 'Engineering & Technology', 'Electrical Engineering', 'Analysis / Calculation', 'Atomic', 'Operational capability to apply Lenz''s Law to transformers, induced EMF under the governing principle''s stated assumptions and validity conditions.', 'Applies to electromagnetic induction and determines the sign/direction of induced response consistently with energy conservation.', 'Use Lenz''s Law to obtain a technically justified analysis, calculation, classification, or decision concerning transformers, induced EMF.', 'Problem data, variables, relationships, assumptions, and boundary conditions relevant to transformers, induced EMF.', 'A princip